try{const saved=JSON.parse(localStorage.getItem(TEMPLATE_DRAFTS)||'null');if(Array.isArray(saved))templateDrafts=saved;}catch{}
try{const saved=JSON.parse(localStorage.getItem(TEMPLATE_RECORDS)||'null');if(saved&&typeof saved==='object')templateRecords=saved;}catch{}
function mergeTemplateRecords(){for(const item of Object.values(templateRecords)){const index=rows.findIndex(row=>row.id===item.id);if(index<0)rows.push(item);else rows[index]={...rows[index],...item};}}
function saveTemplateRecord(row){
 const records={...templateRecords};
 for(const item of rows)records[item.id]=item;
 records[row.id]=row;
 try{localStorage.setItem(TEMPLATE_RECORDS,JSON.stringify(records));}
 catch{toast('无法保存到本浏览器，请检查可用空间后重试');return false;}
 const index=rows.findIndex(item=>item.id===row.id);
 if(index<0)rows.push(row);else rows[index]=row;
 templateRecords=records;
 if(typeof CustomEvent==='function')window.dispatchEvent(new CustomEvent('template-catalog-change'));return true;
}
function saveDraftStorage(next){
 try{localStorage.setItem(TEMPLATE_DRAFTS,JSON.stringify(next));}
 catch{toast('无法保存草稿，请检查浏览器可用空间后重试');return false;}
 templateDrafts=next;return true;
}
function collectTemplateForm(base){const row={...base,entries:[...(base.entries||[])]};if(root?._editCover)row.cover=root._editCover;const panel=root?.querySelector('.admin-drawer');if(!panel)return row;for(const input of panel.querySelectorAll('[data-edit]')){const key=input.dataset.edit;if(key==='vip'||key==='featured')row[key]=input.checked;else if(key==='category')[row.main,row.sub]=input.value.split(' / ');else row[key]=input.value;}if(row.output==='动态文件'){row.selectionMode=panel.querySelector('[name="admin-video-selection"]:checked')?.value||row.selectionMode||'batch';if(row.selectionMode==='batch'){row.min=Number(panel.querySelector('[data-video-min]').value);row.max=Number(panel.querySelector('[data-video-max]').value);row.entries=[];row.refs=0;}else{row.videoEntries=[...panel.querySelectorAll('[data-video-entry]')].map(input=>input.value);row.entries=[...row.videoEntries];row.refs=row.entries.length;}}else{row.entries=[...panel.querySelectorAll('[data-entry]')].map(input=>input.value);row.referenceImages=[...panel.querySelectorAll('[data-admin-action=reference-upload]')].map(button=>button.querySelector('img')?.getAttribute('src')||'');row.refs=row.entries.length;}return row;}
function editingTemplate(){const id=+root?.dataset.editId;return collectTemplateForm(creatingTemplate?.id===id?creatingTemplate:rows.find(row=>row.id===id)||rows[0]);}
function templateSignature(row){return JSON.stringify(translationFields(row).map(field=>String(field[1]||'').trim()));}
function templateReady(row){if(!String(row?.name||'').trim())return false;const fields=translationFields(row),saved=templateTranslationSaved[row.id]||{},signature=templateSignature(row);return ['英语','印地语'].every(lang=>Array.isArray(saved[lang])&&fields.every((field,index)=>!String(field[1]||'').trim()||String(saved[lang][index]||'').trim())&&saved._sources?.[lang]===signature);}
function fillTemplateTranslations(language){const row=editingTemplate();ensureTranslationDraft(row);const languages=language?[language]:['英语','印地语'];for(const lang of languages){templateTranslationDraft[row.id][lang]=translationFields(row).map(field=>String(field[1]||'').trim()?(lang==='中文'?field[1]:'已翻译'):'');if(!translationOrder.includes(lang))translationOrder.push(lang);}renderTranslationTable(row);toast('已翻译，请保存译文；可继续手动修改。');}
function templateDraftBox(){return `<section class="admin-create-upload"><h3>模板草稿箱 <span class="admin-muted">${templateDrafts.length}</span></h3>${templateDrafts.length?templateDrafts.map(draft=>`<div class="admin-draft-row"><div class="admin-draft-thumb">${draft.form.cover?`<img src="${esc(draft.form.cover)}" alt="草稿预览">`:draft.kind==='video'?'视频':'图片'}</div><div><strong>${esc(draft.form.name||draft.file?.name||'未命名模板')}</strong><p class="admin-muted">${draft.kind==='video'?'动态模板':'静态模板'} · ${draft.example?'示例草稿':'已保存草稿'}</p></div><div class="admin-actions"><button type="button" class="admin-btn link" data-admin-action="continue-draft" data-template-draft="${esc(draft.id)}">继续编辑</button><button type="button" class="admin-btn link red" data-admin-action="delete-draft" data-template-draft="${esc(draft.id)}">删除草稿</button></div></div>`).join(''):'<p class="admin-muted">暂无模板草稿</p>'}</section>`;}
function saveTemplateDraft(){saveTemplateVipDraft();if(!createFile){toast('请先上传素材后保存草稿');return;}const form=root.dataset.templateCreateMode==='1'?editingTemplate():creatingTemplate||{...(createType==='video'?rows.find(row=>row.output==='动态文件')||rows[0]:rows[0]),id:Date.now(),name:createFile.name.replace(/\.[^.]+$/,''),desc:'',referenceImages:[],cover:createType==='image'?createFile.url||'':'',status:false,vip:Boolean(templateVipDraft[createType]),featured:Boolean(templateFeaturedDraft[createType]),entries:createType==='video'?[]:['照片'],output:createType==='video'?'动态文件':'静态图片'};const id=activeTemplateDraftId||'template-draft-'+Date.now();const saved={id,kind:createType,file:{...createFile},form:{...form,status:false,_creating:undefined},updatedAt:Date.now()};const index=templateDrafts.findIndex(draft=>draft.id===id);const drafts=[...templateDrafts];if(index<0)drafts.unshift(saved);else drafts[index]=saved;if(!saveDraftStorage(drafts))return;activeTemplateDraftId=null;creatingTemplate=null;closeOverlays();createFile=null;renderCreate();toast('草稿已保存，可在草稿箱继续编辑。');}
function continueTemplateDraft(id){const draft=templateDrafts.find(item=>item.id===id);if(!draft){toast('草稿不存在，请刷新后重试');return;}createType=draft.kind;createFile={...draft.file};creatingTemplate={...draft.form,id:draft.example?Date.now():draft.form.id,entries:[...(draft.form.entries||[])],_creating:true};activeTemplateDraftId=draft.example?null:id;templateVipDraft[createType]=Boolean(draft.form.vip);templateFeaturedDraft[createType]=Boolean(draft.form.featured);createNext();}
function cancelTemplateCreation(){if(root.querySelector('.admin-create-cancel-mask'))return;root.insertAdjacentHTML('beforeend',`<div class="admin-create-cancel-mask"><section role="dialog" aria-modal="true" aria-label="取消创建"><h3>取消创建？</h3><p>退出将放弃本次未保存的内容。</p><div><button type="button" data-admin-action="continue-create">继续编辑</button><button type="button" data-admin-action="discard-create">放弃并取消创建</button></div></section></div>`);root.querySelector('[data-admin-action="continue-create"]').focus();}
function confirmTemplateCreation(){const row=editingTemplate();if(!String(row.name||'').trim()){toast('请填写模板名称');return;}if(row.output==='动态文件'&&row.selectionMode==='batch'&&(row.min<1||row.max<row.min)){toast('最多选择张数不能小于最少选择张数');return;}delete row._creating;delete row.publishedAt;row.status=false;if(!saveTemplateRecord(row))return;window.VIP_FLAGS?.setFlags('template',row.id,{vip:Boolean(row.vip),featured:Boolean(row.featured)});const cleared=!activeTemplateDraftId||saveDraftStorage(templateDrafts.filter(draft=>draft.id!==activeTemplateDraftId));activeTemplateDraftId=null;creatingTemplate=null;createFile=null;closeOverlays();go('templates');toast(cleared?'模板已创建，当前为未上架；完成翻译后才能上架。':'模板已创建，原草稿未能移除。');}
