const categoryTemplateOpen=new Set();
let categoryFilters={name:'',category:'',featured:'',status:'',output:''};
function categoryRows(group,child){return rows.filter(r=>!r.deleted&&r.main===group.name&&(!child||r.sub===child.name)&&(!categoryFilters.name||r.name.toLocaleLowerCase().includes(categoryFilters.name.toLocaleLowerCase()))&&(!categoryFilters.category||r.main===categoryFilters.category||r.sub===categoryFilters.category)&&(!categoryFilters.featured||templateFeatured(r)===(categoryFilters.featured==='是'))&&(!categoryFilters.status||r.status===(categoryFilters.status==='已上架'))&&(!categoryFilters.output||r.output===categoryFilters.output||r.output==='动态文件'&&categoryFilters.output==='动态视频'));}
function categoryCounts(items){return `${items.length}个模板　已上架${items.filter(r=>r.status).length}个　${items.filter(templateFeatured).length}个精选`;}
function categoryCards(items){return `<div class="admin-category-cards">${items.map(r=>`<div class="admin-category-card"><div class="admin-category-card-cover">${r.cover?`<img src="${esc(r.cover)}" alt="${esc(r.name)}">`:`<span>${r.output==='动态文件'?'▶':'模板封面'}</span>`}</div><div><strong>${esc(r.name)}</strong><p><span class="admin-muted">${esc(r.output)}: </span><span>${r.status?'已上架':'未上架'}</span>${templateFeatured(r)?' <span style="color:#409eff">精选</span>':''}</p></div></div>`).join('')}</div>`;}
function renderCategories(){
 const filtered=Object.values(categoryFilters).some(Boolean);
 content.innerHTML=`<h2 style="margin-bottom:5px">分类管理</h2><p class="admin-muted" style="margin:0 0 22px">搜索对象是模板，不是分类名称</p><div class="admin-filters"><label class="admin-field">模板名称<input aria-label="模板名称" data-category-query="name" placeholder="请输入模板名称" value="${esc(categoryFilters.name)}"></label><label class="admin-field">分类${select('category',categoryGroups.flatMap(g=>[g.name,...g.children.map(c=>c.name)]),'筛选模板所属分类')}</label><label class="admin-field">是否精选${select('featured',['是','否'],'筛选分类下模板是否精选')}</label><label class="admin-field">上架状态${select('status',['已上架','未上架'],'筛选分类下模板上架状态')}</label><label class="admin-field">输出形式${select('output',['静态图片','动态视频'],'筛选图片或视频模板')}</label>${btn('重置','category-reset')}${btn('查询','category-query','blue')}${btn('+ 创建一级分类','category-new','blue')}</div><div class="admin-category-results">${categoryGroups.map((g,gi)=>{
 const own=categoryRows(g);if(filtered&&!own.length)return '';
 const children=g.children.map((c,ci)=>({c,ci,items:categoryRows(g,c)})).filter(x=>!filtered||x.items.length),opened=children.filter(x=>x.items.length).every(x=>categoryTemplateOpen.has(gi+':'+x.ci));
 return `<section class="admin-collapse-row"><h3>${children.length?`<button class="admin-category-expand" data-admin-action="category-expand:${gi}">⌄</button>`:''}${esc(g.name)} <small>${categoryCounts(own)}</small><span class="admin-actions">${own.length?btn(opened?'收起模板':'查看模板','category-view:'+gi,'link'):''}${btn('编辑一级','category-edit:'+gi,'link')}${btn('新增二级','category-child-new:'+gi,'link')}</span></h3><div class="admin-category-body">${children.map(({c,ci,items})=>`<div class="admin-category-child"><strong>${esc(c.name)}</strong><small class="admin-muted">${categoryCounts(items)}</small><span class="admin-actions">${items.length?btn(categoryTemplateOpen.has(gi+':'+ci)?'收起模板':'查看模板',`category-view:${gi}:${ci}`,'link'):''}${btn('编辑 / 调整归属',`category-child-edit:${gi}:${ci}`,'link')}</span></div>${categoryTemplateOpen.has(gi+':'+ci)?categoryCards(items):''}`).join('')}</div></section>`;
 }).join('')||'<p class="admin-blank">暂无符合条件的模板</p>'}</div>`;
 for(const input of content.querySelectorAll('select[data-filter]'))input.value=categoryFilters[input.dataset.filter]||'';
}
function queryCategories(){categoryFilters.name=content.querySelector('[data-category-query=name]').value.trim();for(const input of content.querySelectorAll('select[data-filter]'))categoryFilters[input.dataset.filter]=input.value;categoryTemplateOpen.clear();categoryGroups.forEach((g,gi)=>g.children.forEach((c,ci)=>{if(categoryRows(g,c).length)categoryTemplateOpen.add(gi+':'+ci);}));renderCategories();}

