function categoryModal(gi,ci,child=false){const g=categoryGroups[gi],c=child?g?.children[ci]:g;categoryEditing={gi,ci,child};root.querySelectorAll('.admin-shade,.admin-modal').forEach(e=>e.remove());const title=c?(child?'编辑二级分类':'编辑一级分类'):(child?'新增二级分类':'创建一级分类');root.insertAdjacentHTML('beforeend',`<div class="admin-shade" data-admin-action="close-modal"></div><section class="admin-modal" role="dialog" aria-label="${title}"><header>${title}<button class="admin-close" data-admin-action="close-modal">×</button></header><main><div class="admin-inline-form"><label>名称</label><input data-category-field="name" value="${esc(c?.name||'')}" ${help('分类在 App 中展示的名称')}>${child?`<label>所属</label><select data-category-field="parent" ${help('该二级分类所属的一级分类')}>${categoryGroups.map((x,i)=>`<option value="${i}" ${i===gi?'selected':''}>${esc(x.name)}</option>`).join('')}</select>`:''}${['英语','中文','印地语'].map(l=>`<label>${l}译文</label><div style="display:flex;gap:8px"><input data-category-translation="${l}" ${help('该分类的'+l+'名称')} value="${esc(c?.translations?.[l]||(l==='中文'?c?.name||'':''))}">${btn('译','category-translate')}</div>`).join('')}${!child?`<label></label><label style="text-align:left"><input style="width:auto" type="checkbox" data-category-field="shown" ${g?.shown!==false?'checked':''}> 在APP中显示</label>`:''}</div></main><footer>${c?btn('删除分类','category-delete','danger'):''}${btn('取消','close-modal')}${btn('保存分类','category-save','blue')}</footer></section>`);}
function saveCategory(){
 const m=root.querySelector('.admin-modal'),name=m.querySelector('[data-category-field="name"]').value.trim();if(!name){toast('请输入分类名称');return;}
 const {gi,ci,child}=categoryEditing,g=categoryGroups[gi],translations=Object.fromEntries([...m.querySelectorAll('[data-category-translation]')].map(input=>[input.dataset.categoryTranslation,input.value]));
 if(child){const target=+m.querySelector('[data-category-field="parent"]').value,c=ci>=0?g.children[ci]:{};if(categoryGroups[target].children.some(x=>x!==c&&x.name===name)){toast('该一级分类下已存在同名分类');return;}if(ci>=0){rows.filter(r=>r.main===g.name&&r.sub===c.name).forEach(r=>{r.main=categoryGroups[target].name;r.sub=name;});g.children.splice(ci,1);}Object.assign(c,{name,translations});categoryGroups[target].children.push(c);}
 else if(g){if(categoryGroups.some(x=>x!==g&&x.name===name)){toast('已存在同名一级分类');return;}rows.filter(r=>r.main===g.name).forEach(r=>r.main=name);Object.assign(g,{name,translations,shown:m.querySelector('[data-category-field="shown"]').checked});}
 else{if(categoryGroups.some(x=>x.name===name)){toast('已存在同名一级分类');return;}categoryGroups.push({name,translations,shown:m.querySelector('[data-category-field="shown"]').checked,children:[]});}
 closeOverlays();renderCategories();toast('分类已保存到本次演示');
}

