window.ADMIN_UI={mount,go,getTemplate(id){const row=rows.find(item=>String(item.id)===String(id));if(!row)return null;return Object.freeze({id:String(row.id),name:row.name,title:row.name,cover:row.cover||'',output:row.output,vip:templateVip(row),featured:templateFeatured(row),state:row.deleted?'已删除':row.status?'已上架':'已下架',appVisible:!row.deleted&&Boolean(row.status)&&row.appVisible!==false&&row.visible!==false,publishedAt:typeof row.publishedAt==='number'&&Number.isFinite(row.publishedAt)&&row.publishedAt>0?row.publishedAt:null});},startWallpaperCreation(kind='wallpaper-image'){const next=()=>{createType=kind;createFile=null;go('create',true);};if(window.WALLPAPER_EDITOR?.guardExit(next))return;if(window.MEMBER_CONFIG?.guardExit(next))return;next();},get creationLanguages(){return languageRows.map(x=>({name:x.name,display:x.display,code:x.code,enabled:x.enabled}));},adEnabled:(name,audience)=>window.AD_CONFIG?window.AD_CONFIG.isEnabled(name,audience||(window.NEW_UI?.member.active&&window.__DEMO__?.state.logged?'member':'regular')):adRows.find(r=>r.name===name)?.on!==false,get screens(){return [...nativeScreens,...extraScreens,...Object.values(observed.menus||{}).flat().flatMap(x=>x.children||[x])];},get current(){return current;},get root(){return root;},toast,closeOverlays,handleEscape:backendEscape,openDrawer,edit,preview,help,btn,esc,register(screens,renderer){extraScreens.push(...screens);for(const s of screens)customRenderers[s.key]=(el)=>renderer(s.key,el);if(root)renderMenu();},setObserved(data){observed={...observed,...data};if(data.rows){rows=data.rows;mergeTemplateRecords();}if(root)go(current);},registerNative(key,title,renderer,group){customRenderers[key]=renderer;if(group){observed.menus??={};observed.menus[group]??=[];if(!observed.menus[group].some(x=>x.key===key))observed.menus[group].push({key,title});}if(root)renderMenu();}};
document.addEventListener('input',e=>{if(!root?.contains(e.target))return;if(e.target.matches('[data-template-translation-lang]')){const id=+root.dataset.editId,lang=e.target.dataset.templateTranslationLang;templateTranslationDraft[id][lang][+e.target.dataset.templateTranslationIndex]=e.target.value;updateTemplateTranslationStatus(id,lang);}if(e.target.matches('[data-video-min],[data-video-max]'))updateVideoSelection();if(e.target.matches('[data-video-entry]'))e.target.nextElementSibling.textContent=e.target.value.length+'/15';if(e.target.matches('[data-edit="name"],[data-edit="desc"]'))e.target.nextElementSibling.textContent=e.target.value.length+'/'+e.target.maxLength;if(e.target.matches('[data-category-translation-input]')){const i=+e.target.dataset.categoryTranslationInput;translationDraft[i]=e.target.value;const saved=categoryTranslations[translationTarget]||[],changed=translationDraft.filter((x,j)=>x!==(saved[j]||'')).length;root.querySelector('[data-category-status="'+i+'"]').textContent=e.target.value===(saved[i]||'')?'已保存':'未保存';root.querySelector('[data-category-summary]').textContent='已保存 '+(5-changed)+' 项　未保存 '+changed+'　未翻译 '+translationDraft.filter(x=>!x.trim()).length;root.querySelector('[data-admin-action="category-translation-save"]').disabled=!changed;updateCategoryTranslationSummary();}});
document.addEventListener('change',async e=>{if(!root?.contains(e.target))return;if(root.dataset.templateCreateMode==='1'){if(e.target.matches('[data-edit=vip]'))templateVipDraft[createType]=e.target.checked;else if(e.target.matches('[data-edit=featured]'))templateFeaturedDraft[createType]=e.target.checked;}if(e.target.matches('[data-admin-page-size]')){pageSize=Number(e.target.value)||10;page=1;drawRows();}if(e.target.matches('[data-admin-page]')){page=Number(e.target.value)||1;drawRows();}if(e.target.matches('[name="admin-video-selection"]'))renderVideoSelection();if(e.target.id==='admin-edit-video'){const f=e.target.files[0];if(f){if(f.size>30*1024*1024){toast('视频大小不得超过30MB');return;}toast('已选择本地视频：'+f.name+'；未上传线上后台');}}if(e.target.matches('[data-category-target]')){translationTarget=e.target.value;translationDraft=[...(categoryTranslations[translationTarget]||['','','','',''])];renderLanguageTab();}if(e.target.matches('[name="admin-type"]')){const value=e.target.value;const next=()=>{createType=value;createFile=null;creatingTemplate=null;activeTemplateDraftId=null;renderCreate();};if(window.WALLPAPER_EDITOR?.guardExit(next)){for(const radio of content.querySelectorAll('[name="admin-type"]'))radio.checked=radio.value===createType;return;}next();}if(e.target.id==='admin-create-file'){const f=e.target.files[0];if(f){const kind=createType,video=kind==='video';
 const supported=video?/^video\/(mp4|webm)$/:/^image\/(jpeg|png|webp)$/;
 if(!supported.test(f.type)){toast(video?'请选择 MP4 或 WebM 视频':'请选择 JPG、PNG 或 WebP 图片');return;}
 if(f.size>(video?30:10)*1024*1024){toast('素材大小超过限制');return;}const selected={name:f.name,size:f.size,type:f.type,uploading:true};createFile=selected;creatingTemplate=null;activeTemplateDraftId=null;renderCreate();try{const response=await fetch('/api/uploads',{method:'POST',headers:{'Content-Type':f.type||'application/octet-stream','X-File-Name':encodeURIComponent(f.name)},body:f});const data=await response.json();if(!response.ok)throw Error(data.error||'上传失败');if(createFile!==selected||createType!==kind)return;Object.assign(selected,{url:data.url,mimeType:data.mimeType,uploading:false});if(current==='create'){renderCreate();toast('素材已上传，可继续填写配置。');}}catch(error){if(createFile===selected){createFile=null;if(current==='create'){renderCreate();toast(error.message||'素材上传失败，请重试。');}}}}}if(e.target.matches('[data-translation-lang]')){const lang=e.target.dataset.translationLang;if(e.target.checked){if(!translationOrder.includes(lang))translationOrder.push(lang);}else translationOrder=translationOrder.filter(l=>l!==lang);const r=editingTemplate();renderTranslationTable(r);} });
